package com.bankpli.javabank.web;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api")public class MenuController{@GetMapping("/menu")public List<Map<String,String>>menu(){return List.of(item("Customers","/api/customers"),item("Accounts","/api/accounts"),item("Transfers","/api/transfers"),item("Credit","/api/credit"),item("SWIFT & FX","/api/swift"),item("Audit","/api/audit"),item("Batch","/api/batch"),item("Administration","/api/admin"));}private Map<String,String>item(String name,String path){return Map.of("name",name,"path",path);}@GetMapping("/health")public Map<String,String>health(){return Map.of("status","UP","system","Bank PLI");}}
